#include "stdlib/stats/base/ndarray/dmskmax.h"
#include "stdlib/stats/strided/dmskmax.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include <stdint.h>

/**
* Computes the maximum value of a one-dimensional double-precision floating-point ndarray according to a mask.
*
* @param arrays    list containing an input ndarray and a mask ndarray
* @return          maximum value
*/
double stdlib_stats_dmskmax( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const struct ndarray *mask = arrays[ 1 ];
	return API_SUFFIX(stdlib_strided_dmskmax_ndarray)(
		stdlib_ndarray_dimension( x, 0 ),
		(const double *)stdlib_ndarray_data( x ),
		stdlib_ndarray_stride_elements( x, 0 ),
		stdlib_ndarray_offset_elements( x ),
		(const uint8_t *)stdlib_ndarray_data( mask ),
		stdlib_ndarray_stride_elements( mask, 0 ),
		stdlib_ndarray_offset_elements( mask )
	);
}
